Q: Using register/login actions in asp.net mvc A: <p>here for you Admin Controller:</p>
<pre><code>using EntityFrameworkProject.Areas.Admin.ViewModels.CategoryVMs;
using EntityFrameworkProject.Data;
using EntityFrameworkProject.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EntityFrameworkProject.Areas.Admin.Controllers
{
    [Area(&quot;Admin&quot;)]
    [Authorize(Roles = &quot;SuperAdmin, Admin&quot;)]
    public class CategoryController : Controller
    {
        private readonly AppDbContext _context;

        public CategoryController(AppDbContext context)
        {
            _context = context;
        }

        [HttpGet]
        public async Task&lt;IActionResult&gt; Index()
        {
            IEnumerable&lt;Category&gt; categories = await _context.Categories.OrderByDescending(m =&gt; m.Id)
                .Where(c =&gt; !c.IsDeleted).ToListAsync();

            IEnumerable&lt;GetAllCategoryVM&gt; getAllCategoryVMs = categories.Select(c =&gt; new GetAllCategoryVM()
            {
                Id = c.Id,
                Name = c.Name
            });

            return View(getAllCategoryVMs);
        }

        [HttpGet]
        public IActionResult Create()
        {
            return View();
        }

        [HttpPost]
        public async Task&lt;IActionResult&gt; Create(CreateCategoryVM request)
        {
            if (!ModelState.IsValid) return View();

            bool isExist = await _context.Categories.AnyAsync(c =&gt; c.Name.Trim().ToLower() == request.Name.Trim().ToLower());

            if (isExist)
            {
                ModelState.AddModelError(&quot;Name&quot;, &quot;Bu adda movcuddur!&quot;);
                return View();
            }

            Category newCategory = new()
            {
                Name = request.Name
            };

            await _context.Categories.AddAsync(newCategory);
            await _context.SaveChangesAsync();

            return RedirectToAction(nameof(Index));
        }

        [HttpGet]
        public async Task&lt;IActionResult&gt; Detail(int? id)
        {
            if (id is null) return BadRequest();

            Category category = await _context.Categories.FirstOrDefaultAsync(c =&gt; c.Id == id &amp;&amp; !c.IsDeleted);

            if (category == null) return NotFound();

            DetailCategoryVM detailCategoryVM = new()
            {
                Id = category.Id,
                Name = category.Name
            };

            return View(detailCategoryVM);
        }

        [HttpGet]
        public async Task&lt;IActionResult&gt; Update(int? id)
        {
            if (id is null) return BadRequest();

            Category category = await _context.Categories.FirstOrDefaultAsync(c =&gt; c.Id == id &amp;&amp; !c.IsDeleted);

            if (category == null) return NotFound();

            UpdateCategoryVM updateCategoryVM = new()
            {
                Name = category.Name
            };

            return View(updateCategoryVM);
        }

        [HttpPost]
        public async Task&lt;IActionResult&gt; Update(int? id, UpdateCategoryVM request)
        {
            if (id is null) return BadRequest();

            if (!ModelState.IsValid) return View();

            Category category = await _context.Categories.FirstOrDefaultAsync(c =&gt; c.Id == id &amp;&amp; !c.IsDeleted);
            if (category == null) return NotFound();

            bool isExist = await _context.Categories.AnyAsync(c =&gt; c.Name.Trim().ToLower() == request.Name.Trim().ToLower() &amp;&amp; c.Id != id);

            if (isExist)
            {
                ModelState.AddModelError(&quot;Name&quot;, &quot;Bu adda movcuddur!&quot;);
                return View();
            }

            //Category updateCategory = new()
            //{
            //    Id = category.Id,
            //    Name = request.Name
            //};

            //_context.Categories.Update(updateCategory);

            category.Name = request.Name;

            await _context.SaveChangesAsync();
            return RedirectToAction(nameof(Index));
        }

        [HttpPost]
        [Authorize(Roles = &quot;SuperAdmin&quot;)]
        public async Task&lt;IActionResult&gt; Delete(int? id)
        {
            if (id is null) return BadRequest();

            Category category = await _context.Categories.FirstOrDefaultAsync(c =&gt; c.Id == id &amp;&amp; !c.IsDeleted);
            if (category == null) return NotFound();

            //category.IsDeleted = true;

            _context.Categories.Remove(category);
            await _context.SaveChangesAsync();

            return RedirectToAction(nameof(Index));
        }
    }
}
