<pre><code>using EntityFrameworkProject.Areas.Admin.ViewModels.ProductVMs;
using EntityFrameworkProject.Data;
using EntityFrameworkProject.Helpers;
using EntityFrameworkProject.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;

namespace EntityFrameworkProject.Areas.Admin.Controllers
{
    [Area(&quot;Admin&quot;)]
    [Authorize(Roles = &quot;SuperAdmin, Admin&quot;)]
    public class ProductController : Controller
    {
        private readonly AppDbContext _context;
        private readonly IWebHostEnvironment _env;

        public ProductController(AppDbContext context, IWebHostEnvironment env)
        {
            _context = context;
            _env = env;
        }

        public async Task&lt;IActionResult&gt; Index(int page = 1, int take = 5)
        {
            // 1) Get distinct product ids from ProductTags (SQL-translatable)
            var productIds = await _context.ProductTags
                .Where(pt =&gt; !pt.IsDeleted)
                .Select(pt =&gt; pt.ProductId)
                .Distinct()
                .OrderByDescending(id =&gt; id) // stable ordering for pagination
                .Skip((page * take) - take)
                .Take(take)
                .ToListAsync();

            // 2) Load products and necessary navigations for those ids
            var products = await _context.Products
                .Where(p =&gt; productIds.Contains(p.Id) &amp;&amp; !p.IsDeleted)
                .Include(p =&gt; p.ProductImages)
                .Include(p =&gt; p.Category)
                .Include(p =&gt; p.ProductTags)
                .ThenInclude(pt =&gt; pt.Tag)
                .OrderByDescending(p =&gt; p.Id) // match ordering
                .ToListAsync();

            // 4) Project to VM in memory (safe and simple)
            var getAllProductVMs = products
                .Select(p =&gt; new GetAllProductVM
                {
                    Id = p.Id,
                    MainImage = p.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image,
                    Name = p.Name,
                    Price = p.Price,
                    CategoryName = p.Category?.Name,
                    Tags = p.ProductTags.Select(pt =&gt; pt.Tag.Name).ToList()
                })
                .ToList();

            int pageCount = await GetPageCount(take);

            Paginate&lt;GetAllProductVM&gt; paginate = new(getAllProductVMs, page, pageCount);

            return View(paginate);
        }

        public async Task&lt;int&gt; GetPageCount(int take)
        {
            int count = await _context.Products.Where(m =&gt; !m.IsDeleted).CountAsync();
            return (int)Math.Ceiling((decimal)count / take);
        }

        public async Task&lt;IActionResult&gt; Create()
        {
            ViewBag.Categories = await GetAllCategories();
            ViewBag.Tags = await GetAllTags();
            return View();
        }

        [HttpPost]
        public async Task&lt;IActionResult&gt; Create(CreateProductVM request)
        {
            if (!ModelState.IsValid)
            {
                ViewBag.Categories = await GetAllCategories();
                ViewBag.Tags = await GetAllTags();
                return View();
            }

            if (!request.MainImage.CheckFileType(&quot;image/&quot;))
            {
                ViewBag.Categories = await GetAllCategories();
                ViewBag.Tags = await GetAllTags();

                ModelState.AddModelError(&quot;MainImage&quot;, &quot;Shekil tipinde olmalidir!&quot;);
                return View();
            }

            if (request.MainImage.CheckFileSize(2000))
            {
                ViewBag.Categories = await GetAllCategories();
                ViewBag.Tags = await GetAllTags();

                ModelState.AddModelError(&quot;MainImage&quot;, &quot;Shekil max 2mb olmalidir!&quot;);
                return View();
            }

            foreach (var item in request.AdditionalImages)
            {
                if (!item.CheckFileType(&quot;image/&quot;))
                {
                    ViewBag.Categories = await GetAllCategories();
                    ViewBag.Tags = await GetAllTags();

                    ModelState.AddModelError(&quot;AdditionalImages&quot;, &quot;Shekil tipinde olmalidir!&quot;);
                    return View();
                }

                if (item.CheckFileSize(2000))
                {
                    ViewBag.Categories = await GetAllCategories();
                    ViewBag.Tags = await GetAllTags();

                    ModelState.AddModelError(&quot;AdditionalImages&quot;, &quot;Shekil max 2mb olmalidir!&quot;);
                    return View();
                }
            }

            bool isExist = await _context.Categories.AnyAsync(c =&gt; c.Id == request.CategoryId &amp;&amp; !c.IsDeleted);

            if (!isExist)
            {
                ViewBag.Categories = await GetAllCategories();
                ViewBag.Tags = await GetAllTags();

                ModelState.AddModelError(&quot;CategoryId&quot;, &quot;Category tapilmadi!&quot;);
                return View();
            }

            List&lt;ProductImage&gt; productImages = new();

            string mainFileName = request.MainImage.GenerateFileName();
            string mainImagePath = _env.WebRootPath.GetFilePath(&quot;img&quot;, mainFileName);
            request.MainImage.SaveFile(mainImagePath);

            ProductImage newMainImage = new()
            {
                Image = mainFileName,
                IsMain = true
            };

            productImages.Add(newMainImage);

            foreach (var item in request.AdditionalImages)
            {
                string additionalFileName = item.GenerateFileName();
                string additionalImagePath = _env.WebRootPath.GetFilePath(&quot;img&quot;, additionalFileName);
                item.SaveFile(additionalImagePath);

                ProductImage newAdditionalImage = new()
                {
                    Image = additionalFileName
                };

                productImages.Add(newAdditionalImage);
            }

            Product newProduct = new()
            {
                Name = request.Name,
                Description = request.Description,
                Price = request.Price,
                CategoryId = request.CategoryId,
                ProductImages = productImages
            };

            await _context.Products.AddAsync(newProduct);
            await _context.SaveChangesAsync();

            foreach (var tagId in request.TagIds)
            {
                ProductTag productTag = new()
                {
                    ProductId = newProduct.Id,
                    TagId = tagId
                };

                await _context.ProductTags.AddAsync(productTag);
            }

            await _context.SaveChangesAsync();

            return RedirectToAction(nameof(Index));
        }

        public async Task&lt;IActionResult&gt; Update(int? id)
        {
            if (id == null) return BadRequest();

            // 1) Get distinct product ids from ProductTags (SQL-translatable)
            var productId = await _context.ProductTags
                .Where(pt =&gt; !pt.IsDeleted &amp;&amp; pt.ProductId == id)
                .Select(pt =&gt; pt.ProductId)
                .Distinct()
                .FirstOrDefaultAsync();

            // 2) Load products and necessary navigations for those ids
            var product = await _context.Products
                .Where(p =&gt; p.Id == productId &amp;&amp; !p.IsDeleted)
                .Include(p =&gt; p.ProductImages)
                .Include(p =&gt; p.Category)
                .Include(p =&gt; p.ProductTags)
                .ThenInclude(pt =&gt; pt.Tag)
                .FirstOrDefaultAsync();

            if (product == null) return NotFound();

            var tagIds = product.ProductTags.Select(pt =&gt; pt.TagId).ToList();

            var tags = await _context.Tags
                .Where(t =&gt; !t.IsDeleted &amp;&amp; !tagIds.Contains(t.Id))
                .ToListAsync();

            ViewBag.Categories = await GetAllCategories();
            ViewBag.Tags = tags;

            UpdateProductVM updateProductVM = new()
            {
                Id = product.Id,
                Name = product.Name,
                Description = product.Description,
                Price = product.Price,
                CategoryId = product.CategoryId.Value,
                MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image,
                AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList(),
                Tags = product.ProductTags
            };

            return View(updateProductVM);
        }

        [HttpPost]
        public async Task&lt;IActionResult&gt; Update(int? id, UpdateProductVM request)
        {
            if (id == null) return BadRequest();

            Product? product = await _context.Products
    .Include(p =&gt; p.ProductImages)
    .FirstOrDefaultAsync(p =&gt; !p.IsDeleted &amp;&amp; p.Id == id);

            if (product == null) return NotFound();

            bool isExist = await _context.Categories.AnyAsync(c =&gt; c.Id == request.CategoryId &amp;&amp; !c.IsDeleted);

            if (!isExist)
            {
                ViewBag.Categories = await GetAllCategories();

                request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                ModelState.AddModelError(&quot;CategoryId&quot;, &quot;Category tapilmadi!&quot;);
                return View(request);
            }

            if (!ModelState.IsValid)
            {
                ViewBag.Categories = await GetAllCategories();

                request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                return View(request);
            }

            if (request.MainImage != null)
            {
                if (!request.MainImage.CheckFileType(&quot;image/&quot;))
                {
                    ViewBag.Categories = await GetAllCategories();

                    request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                    request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                    ModelState.AddModelError(&quot;MainImage&quot;, &quot;Shekil tipinde olmalidir!&quot;);
                    return View(request);
                }

                if (request.MainImage.CheckFileSize(2000))
                {
                    ViewBag.Categories = await GetAllCategories();

                    request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                    request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                    ModelState.AddModelError(&quot;MainImage&quot;, &quot;Shekil max 2mb olmalidir!&quot;);
                    return View(request);
                }
            }

            if (request.AdditionalImages != null)
            {
                foreach (var item in request.AdditionalImages)
                {
                    if (!item.CheckFileType(&quot;image/&quot;))
                    {
                        ViewBag.Categories = await GetAllCategories();

                        request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                        request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                        ModelState.AddModelError(&quot;AdditionalImages&quot;, &quot;Shekil tipinde olmalidir!&quot;);
                        return View(request);
                    }

                    if (item.CheckFileSize(2000))
                    {
                        ViewBag.Categories = await GetAllCategories();

                        request.MainPhoto = product.ProductImages.FirstOrDefault(pi =&gt; pi.IsMain)?.Image;
                        request.AdditionalPhotos = product.ProductImages.Where(pi =&gt; !pi.IsMain).Select(pi =&gt; pi.Image).ToList();

                        ModelState.AddModelError(&quot;AdditionalImages&quot;, &quot;Shekil max 2mb olmalidir!&quot;);
                        return View(request);
                    }
                }
            }

            if (request.MainImage != null)
            {
                string oldMainPath = _env.WebRootPath.GetFilePath(&quot;img&quot;, product.ProductImages
                    .FirstOrDefault(pi =&gt; pi.IsMain)?.Image);
                oldMainPath.DeleteFile();

                string mainFileName = request.MainImage.GenerateFileName();
                string mainPath = _env.WebRootPath.GetFilePath(&quot;img&quot;, mainFileName);
                request.MainImage.SaveFile(mainPath);

                product.ProductImages.FirstOrDefault(p =&gt; p.IsMain)?.Image = mainFileName;
            }

            if (request.AdditionalImages != null)
            {
                var oldAdditionalImages = product.ProductImages.Where(pi =&gt; !pi.IsMain).ToList();

                foreach (var item in oldAdditionalImages)
                {
                    string oldAdditionalPath = _env.WebRootPath.GetFilePath(&quot;img&quot;, item.Image);
                    oldAdditionalPath.DeleteFile();
                }

                foreach (var item in request.AdditionalImages)
                {
                    string additioanlFileName = item.GenerateFileName();
                    string additionalPath = _env.WebRootPath.GetFilePath(&quot;img&quot;, additioanlFileName);
                    item.SaveFile(additionalPath);

                    product.ProductImages.FirstOrDefault(p =&gt; !p.IsMain)?.Image = additioanlFileName;
                }
            }

            product.Name = request.Name;
            product.Description = request.Description;
            product.Price = request.Price;
            product.CategoryId = request.CategoryId;

            await _context.SaveChangesAsync();

            return RedirectToAction(nameof(Index));
        }

        public async Task&lt;IActionResult&gt; Detail(int? id)
        {
            if (id is null) return BadRequest();

            Product? product = await _context.Products
                .Include(m =&gt; m.ProductImages)
                .Include(m =&gt; m.Category)
                .FirstOrDefaultAsync(m =&gt; m.Id == id &amp;&amp; !m.IsDeleted);

            if (product == null) return NotFound();

            DetailProductVM detailProductVM = new()
            {
                Name = product.Name,
                Description = product.Description,
                Price = product.Price,
                CategoryName = product.Category.Name,
                ProductImages = product.ProductImages
            };

            return View(detailProductVM);
        }

        public async Task&lt;IActionResult&gt; Delete(int? id)
        {
            if (id == null) return BadRequest();

            Product? product = await _context.Products.FirstOrDefaultAsync(m =&gt; m.Id == id &amp;&amp; !m.IsDeleted);

            if (product == null) return NotFound();

            _context.Products.Remove(product);
            await _context.SaveChangesAsync();

            return RedirectToAction(nameof(Index));
        }

        public async Task&lt;IActionResult&gt; DeleteTag(int? id, int? productId)
        {
            if (id is null || productId is null) return BadRequest();

            ProductTag? productTag = await _context.ProductTags.FirstOrDefaultAsync(pt =&gt; pt.TagId == id &amp;&amp; pt.ProductId == productId &amp;&amp; !pt.IsDeleted);

            if (productTag == null) return NotFound();

            _context.ProductTags.Remove(productTag);
            await _context.SaveChangesAsync();

            Tag tag = await _context.Tags.FirstOrDefaultAsync(t =&gt; t.Id == id &amp;&amp; !t.IsDeleted);

            return Ok(tag);
        }

        public async Task&lt;SelectList&gt; GetAllCategories()
        {
            var categories = await _context.Categories
                .Where(c =&gt; !c.IsDeleted)
                .ToListAsync();

            return new SelectList(categories, &quot;Id&quot;, &quot;Name&quot;);
        }

        public async Task&lt;SelectList&gt; GetAllTags()
        {
            var tags = await _context.Tags
                .Where(c =&gt; !c.IsDeleted)
                .ToListAsync();

            return new SelectList(tags, &quot;Id&quot;, &quot;Name&quot;);
        }
    }
}
